from typing import List
from collections import deque

def maxMoves(kx: int, ky: int, positions: List[List[int]]) -> int:
    # Precompute distances from all points of interest (knight start + pawns)
    # Since board is small (50x50), we can use BFS for each pawn.
    all_pts = [[kx, ky]] + positions
    dist_map = {}

    for i, (sx, sy) in enumerate(all_pts):
        dists = [[-1] * 50 for _ in range(50)]
        dists[sx][sy] = 0
        q = deque([(sx, sy)])
        while q:
            x, y = q.popleft()
            for dx, dy in [(2,1),(2,-1),(-2,1),(-2,-1),(1,2),(1,-2),(-1,2),(-1,-2)]:
                nx, ny = x + dx, y + dy
                if 0 <= nx < 50 and 0 <= ny < 50 and dists[nx][ny] == -1:
                    dists[nx][ny] = dists[x][y] + 1
                    q.append((nx, ny))
        dist_map[(sx, sy)] = dists

    # Precompute distances between all pawns and the starting knight position
    # matrix[i][j] is distance from pawn i to pawn j (where index 0 is start)
    n = len(positions)
    adj = [[0] * (n + 1) for _ in range(n + 1)]
    for i in range(n + 1):
        px, py = all_pts[i]
        for j in range(n + 1):
            jx, jy = all_pts[j]
            adj[i][j] = dist_map[(px, py)][jx][jy]

    memo = {}

    def solve(curr_idx: int, mask: int) -> int:
        if mask == (1 << n) - 1:
            return 0
        if (curr_idx, mask) in memo:
            return memo[(curr_idx, mask)]

        # Alice wants to maximize, Bob wants to minimize
        # Turn is determined by number of bits set in mask
        turn_alice = (bin(mask).count('1') % 2 == 0)

        res = float('-inf') if turn_alice else float('inf')

        for i in range(n):
            if not (mask & (1 << i)):
                # Distance from current knight position to pawn i
                d = adj[curr_idx][i + 1]
                score = d + solve(i + 1, mask | (1 << i))

                if turn_alice:
                    res = max(res, score)
                else:
                    res = min(res, score)

        memo[(curr_idx, mask)] = res
        return res

    # The initial knight is at index 0 in all_pts
    return solve(0, 0)
```

這是一個典型的**動態規劃 (DP) 搭配 位元遮罩 (Bitmask)** 的問題。由於棋盤較小且 `positions` 長度最多只有 15，我們可以用位元遮罩來記錄哪些棋子已經被吃掉。

核心邏輯：
1. 先用 **BFS** 計算從任何一個點到所有棋子的最短路徑（預處理距離矩陣）。
2. 使用 **Memoization (記憶化)** 處理遞迴。
3. Alice 最大化總步數，Bob 最小化總步數。

