from typing import List
from collections import deque

def maxMoves(kx: int, ky: int, positions: List[List[int]]) -> int:
    # BFS to pre-calculate shortest paths between all relevant points
    # Points include the starting knight position and all pawn positions
    all_points = [(kx, ky)] + positions
    n = len(all_points)
    dist = [[float('inf')] * n for _ in range(n)]

    knight_moves = [
        (2, 1), (2, -1), (-2, 1), (-2, -1),
        (1, 2), (1, -2), (-1, 2), (-1, -2)
    ]

    for i in range(n):
        dist[i][i] = 0
        queue = deque([i])
        # Temporary BFS for point i to all other points
        d_tmp = [float('inf')] * n
        d_tmp[i] = 0
        while queue:
            u_idx = queue.popleft()
            ux, uy = all_points[u_idx]
            for dx, dy in knight_moves:
                vx, vy = ux + dx, uy + dy
                if 0 <= vx < 50 and 0 <= vy < 50:
                    # Check if this move lands on any of our points of interest
                    for v_idx in range(n):
                        if all_points[v_idx] == (vx, vy):
                            if d_tmp[v_idx] == float('inf'):
                                d_tmp[v_idx] = d_tmp[u_idx] + 1
                                queue.append(v_idx)
        dist[i] = d_tmp

    memo = {}

    def solve(curr_idx: int, mask: int) -> int:
        if mask == (1 << n) - 1:
            return 0
        if (curr_idx, mask) in memo:
            return memo[(curr_idx, mask)]

        # Determine whose turn it is by counting bits set in mask
        # Alice goes first. If number of bits set is even, it's Alice's turn.
        bits_set = bin(mask).count('1')
        is_alice = (bits_set % 2 == 0)

        res = float('-inf') if is_alice else float('inf')

        for i in range(n):
            # If pawn i exists and is not the current knight position
            if not (mask & (1 << i)) and i != 0:
                # Special case: The starting point (index 0) is NOT a pawn to be captured
                # But we must ensure we only pick from actual pawns (indices 1 to n-1)
                if i > 0:
                    score = dist[curr_idx][i] + solve(i, mask | (1 << i))
                    if is_alice:
                        res = max(res, score)
                    else:
                        res = min(res, score)

        memo[(curr_idx, mask)] = res
        return res

    # Initial call: knight at index 0, no pawns captured (mask 0)
    # Note: We need to treat the starting position as 'visited' in the bitmask sense 
    # because we don't want to "capture" it, but for simplicity, let's just handle 
    # indices carefully. Let's use a mask where bit i means pawn i is captured.
    # The knight's current position index doesn't need to be in the mask unless it's a pawn.

    # Re-adjusting: mask represents pawns (indices 1 to n-1)
    # Let's simplify: bits in mask = pawns captured.
    memo = {}
    def solve_final(curr_idx, mask):
        if mask == (1 << (n-1)) - 1: # All pawns (from index 1 to n-1) captured
            return 0
        if (curr_idx, mask) in memo:
            return memo[(curr_idx, mask)]

        # Count how many pawns are already captured to see whose turn it is
        # Alice starts first.
        captured_count = bin(mask).count('1')
        is_alice = (captured_count % 2 == 0)

        res = float('-inf') if is_alice else float('inf')

        for i in range(1, n): # Only indices 1 to n-1 are pawns
            if not (mask & (1 << (i - 1))):
                score = dist[curr_idx][i] + solve_final(i, mask | (1 << (i - 1)))
                if is_alice:
                    res = max(res, score)
                else:
                    res = min(res, score)

        memo[(curr_idx, mask)] = res
        return res

    # The bitmask only tracks pawns (positions[0...m-1]), which are indices 1...n-1 in all_points
    # Since positions.length <= 15, this is efficient.
    # Correcting the solve_final call to match:
    memo = {}
    def solve_correct(curr_idx, mask):
        if mask == (1 << (n - 1)) - 1:
            return 0
        if (curr_idx, mask) in memo:
            return memo[(curr_idx, mask)]

        captured_count = bin(mask).count('1')
        is_alice = (captured_count % 2 == 0)

        res = float('-inf') if is_alice else float('inf')
        for i in range(1, n):
            if not (mask & (1 << (i - 1))):
                score = dist[curr_idx][i] + solve_correct(i, mask | (1 << (i-1)))
                if is_alice: res = max(res, score)
                else: res = min(res, score)
        memo[(curr_idx, mask)] = res
        return res

    # Wait, the logic above handles "all pawns captured". 
    # But there are len(positions) pawns. Let m = len(positions).
    # The bitmask should be of size m.
    m = len(positions)
    memo = {}
    def solve_final_fixed(curr_idx, mask):
        if mask == (1 << m) - 1:
            return 0
        if (curr_idx, mask) in memo:
            return memo[(curr_idx, mask)]

        captured_count = bin(mask).count('1')
        is_alice = (captured_count % 2 == 0)

        res = float('-inf') if is_alice else float('inf')
        for i in range(m): # i refers to index in 'positions' array
            if not (mask & (1 << i)):
                # all_points[i+1] corresponds to positions[i]
                score = dist[curr_idx][i+1] + solve_final_fixed(i+1, mask | (1 << i))
                if is_alice: res = max(res, score)
                else: res = min(res, score)
        memo[(curr_idx, mask)] = res
        return res

    return solve_final_fixed(0, 0)
