def maxMoves(kx: int, ky: int, positions: List[List[int]]) -> int:
    # points[0] is knight start, points[1...N] are pawns
    points = [[kx, ky]] + positions
    num_points = len(points)
    dist = [[float('inf')] * num_points for _ in range(num_points)]

    knight_moves = [
        (2, 1), (2, -1), (-2, 1), (-2, -1),
        (1, 2), (1, -2), (-1, 2), (-1, -2)
    ]

    # Pre-calculate shortest paths between all points of interest on a 50x50 board
    for i in range(num_points):
        start_x, start_y = points[i]
        d_map = [[-1] * 50 for _ in range(50)]
        d_map[start_x][start_y] = 0
        queue = deque([(start_x, start_y)])

        while queue:
            cx, cy = queue.popleft()
            for dx, dy in knight_moves:
                nx, ny = cx + dx, cy + dy
                if 0 <= nx < 50 and 0 <= ny < 50 and d_map[nx][ny] == -1:
                    d_map[nx][ny] = d_map[cx][cy] + 1
                    queue.append((nx, ny))

        for j in range(num_points):
            px, py = points[j]
            dist[i][j] = d_map[px][py]

    memo = {}

    def solve(mask: int, last_idx: int) -> int:
        # mask represents captured pawns (indices 0 to len(positions)-1)
        if mask == (1 << len(positions)) - 1:
            return 0

        state = (mask, last_idx)
        if state in memo:
            return memo[state]

        # Determine turn: Alice goes first. 
        # If number of pawns captured is even, it's Alice's turn.
        captured_count = bin(mask).count('1')
        is_alice = (captured_count % 2 == 0)

        if is_alice:
            res = -float('inf')
        else:
            res = float('inf')

        for i in range(len(positions)):
            if not (mask & (1 << i)):
                # pawn index in 'points' array is i + 1
                moves = dist[last_idx][i + 1]
                score = moves + solve(mask | (1 << i), i + 1)

                if is_alice:
                    if score > res:
                        res = score
                else:
                    if score < res:
                        res = score

        memo[state] = int(res) if res != float('inf') and res != -float('inf') else res
        return memo[state]

    # The knight starts at points[0], no pawns captured yet.
    return solve(0, 0)

