import collections
from typing import List

def maxMoves(kx: int, ky: int, positions: List[List[int]]) -> int:
    # Precompute distances between all points (knight start + all pawns)
    nodes = [(kx, ky)] + [tuple(p) for p in positions]
    n = len(nodes)
    dist_matrix = [[float('inf')] * n for _ in range(n)]

    for i in range(n):
        start_x, start_y = nodes[i]
        dist_matrix[i][i] = 0
        queue = collections.deque([(start_x, start_y, 0)])
        visited = {(start_x, start_y)}
        while queue:
            curr_x, curr_y, d = queue.popleft()
            for j in range(n):
                if nodes[j] == (curr_x, curr_y):
                    dist_matrix[i][j] = min(dist_matrix[i][j], d)
            for dx, dy in [(2, 1), (2, -1), (-2, 1), (-2, -1), (1, 2), (1, -2), (-1, 2), (-1, -2)]:
                nx, ny = curr_x + dx, curr_y + dy
                if 0 <= nx < 50 and 0 <= ny < 50 and (nx, ny) not in visited:
                    visited.add((nx, ny))
                    queue.append((nx, ny, d + 1))

    memo = {}

    def solve(current_node_idx, mask):
        if mask == 0:
            return 0
        state = (current_node_idx, mask)
        if state in memo:
            return memo[state]

        remaining_count = bin(mask).count('1')
        # Alice goes first. If total pawns - remaining count is even, it's Alice's turn.
        is_alice = (len(positions) - remaining_count) % 2 == 0

        res = float('-inf') if is_alice else float('inf')

        for i in range(1, n):
            if (mask >> (i - 1)) & 1:
                d = dist_matrix[current_node_idx][i]
                # The problem says "captures it in the fewest possible moves". 
                # This means we use precomputed shortest paths.
                score = d + solve(i, mask ^ (1 << (i - 1)))
                if is_alice:
                    res = max(res, score)
                else:
                    res = min(res, score)

        memo[state] = res
        return res

    initial_mask = (1 << len(positions)) - 1
    result = solve(0, initial_mask)
    return int(result)
