def numberOfSubstrings(s: str, k: int) -> int:
    n = len(s)
    count = 0
    for i in range(n):
        freq = {}
        for j in range(i, n):
            char = s[j]
            freq[char] = freq.get(char, 0) + 1
            if freq[char] >= k:
                count += (n - j)
                break
    return count
