from typing import List

def maxRectangleArea(points: List[List[int]]) -> int:
    n = len(points)
    max_area = -1

    # Try every combination of 4 points to see if they form a valid rectangle
    for i in range(n):
        for j in range(i + 1, n):
            for k in range(j + 1, n):
                for l in range(k + 1, n):
                    p = [points[i], points[j], points[k], points[l]]

                    # Extract unique x and y coordinates from the 4 selected points
                    xs = sorted(list(set(pt[0] for pt in p)))
                    ys = sorted(list(set(pt[1] for pt in p)))

                    # A rectangle parallel to axes must have exactly 2 unique x and 2 unique y coords
                    if len(xs) == 2 and len(ys) == 2:
                        x1, x2 = xs
                        y1, y2 = ys

                        # Verify if these 4 points are the 4 corners of this rectangle
                        corners = [(x1, y1), (x1, y2), (x2, y1), (x2, y2)]
                        if sorted(p) == sorted(corners):
                            area = (x2 - x1) * (y2 - y1)

                            # Check if any other point from the input is inside or on the border
                            is_valid = True
                            for m in range(n):
                                pt_m = points[m]
                                # If it's one of the 4 corners, skip it
                                if pt_m in p:
                                    continue

                                # Check if point is inside or on the boundary
                                if x1 <= pt_m[0] <= x2 and y1 <= pt_m[1] <= y2:
                                    is_valid = False
                                    break

                            if is_valid:
                                if area > max_area:
                                    max_area = area

    return max_area
