```python
import bisect
from typing import List

def maximumWeight(intervals: List[List[int]]) -> List[int]:
    n = len(intervals)
    # 儲存 (l, r, w, original_index) 並按結束位置排序
    data = sorted([(intervals[i][0], intervals[i][1], intervals[i][2], i) for i in range(n)], key=lambda x: x[1])
    ends = [x[1] for x in data]

    # dp[k][i] 代表選取剛好 k 個區間且最後一個是第 i 個區間的 (權重, 索引列表)
    dp = [[(-1, []) for _ in range(n)] for _ in range(5)]
    # prefix_max[k][i] 代表前 i 個區間中選取剛好 k 個的最大權重與對應索引列表
    prefix_max = [[(-1, []) for _ in range(n + 1)] for _ in range(5)]

    for k in range(5):
        prefix_max[k][0] = (0, [])

    for k in range(1, 5):
        for i in range(n):
            l, r, w, idx = data[i]
            p = bisect.bisect_left(ends, l) - 1

            # 如果要選 k 個，前面的必須是 k-1 個且不重疊
            if k == 1:
                dp[k][i] = (w, [idx])
            elif p >= 0:
                prev_w, prev_idxs = prefix_max[k-1][p+1]
                if prev_w != -1:
                    dp[k][i] = (w + prev_w, sorted(prev_idxs + [idx]))

            # 更新 prefix_max 供下一層使用
            curr_w, curr_idxs = dp[k][i]
            best_w, best_idxs = prefix_max[k][i+1]
            if curr_w > best_w:
                prefix_max[k][i+1] = (curr_w, curr_idxs)
            elif curr_w == best_w and curr_w != -1:
                if not best_idxs or curr_idxs < best_idxs:
                    prefix_max[k][i+1] = (curr_w, curr_idxs)
            else:
                prefix_max[k][i+1] = prefix_max[k][i] # 這裡應該是繼承前一個位置的最優值，修正如下：

        # 正確的 prefix_max 更新邏輯
        for i in range(n):
            curr_w, curr_idxs = dp[k][i]
            prev_best_w, prev_best_idxs = prefix_max[k][i]
            if curr_w > prev_best_w:
                prefix_max[k][i+1] = (curr_w, curr_idxs)
            elif curr_w == prev_best_w and curr_w != -1:
                if not prev_best_idxs or curr_idxs < prev_best_idxs:
                    prefix_max[k][i+1] = (curr_w, curr_idxs)
            else:
                prefix_max[k][i+1] = prefix_max[k][i]

    # 找出所有 k 在 [1,4] 且權重最大的結果
    ans_w = -1
    ans_idx = []
    for k in range(1, 5):
        for i in range(n):
            w, idxs = dp[k][i]
            if w > ans_w:
                ans_w = w
                ans_idx = idxs
            elif w == ans_w and w != -1:
                if not ans_idx or idxs < ans_idx:
                    ans_idx = idxs

    return ans_idx
