```python
import bisect
from typing import List

def maximumWeight(intervals: List[List[int]]) -> List[int]:
    n = len(intervals)
    # data 包含 (l, r, w, original_index)
    data = []
    for i in range(n):
        data.append((intervals[i][0], intervals[i][1], intervals[i][2], i))

    # 按結束位置排序
    data.sort(key=lambda x: (x[1], x[0]))
    ends = [x[1] for x in data]

    # dp[k][i]: 選取剛好 k 個區間，最後一個是第 i 個（在 sorted data 中的索引）
    dp = [[(-1, []) for _ in range(n)] for _ in range(5)]
    # prefix_max[k][i]: 前 i 個區間中選取剛好 k 個的 лучший 結果
    prefix_max = [[(-1, []) for _ in range(n + 1)] for _ in range(5)]

    for k in range(5):
        prefix_max[k][0] = (0, [])

    for k in range(1, 5):
        for i in range(n):
            l, r, w, idx = data[i]
            if k == 1:
                dp[k][i] = (w, [idx])
            else:
                p = bisect.bisect_left(ends, l) - 1
                if p >= 0:
                    prev_w, prev_idxs = prefix_max[k-1][p+1]
                    if prev_w != -1:
                        dp[k][i] = (w + prev_w, sorted(prev_idxs + [idx]))

            # 更新當前 k 的 prefix_max
            curr_w, curr_idxs = dp[k][i]
            best_w, best_idxs = prefix_max[k][i+1]
            if curr_w > best_w:
                prefix_max[k][i+1] = (curr_w, curr_idxs)
            elif curr_w == best_w and curr_w != -1:
                if not best_idxs or curr_idxs < best_idxs:
                    prefix_max[k][i+1] = (curr_w, curr_idxs)
            else:
                # 這裡需要確保 prefix_max 是非遞減的，如果當前位置沒更新，保留前一個最好的
                if prev_best_w := prefix_max[k][i][0] > -1:
                    pass # 此處邏輯由迴圈順序處理

        # 重寫一遍 prefix_max 的填充以確保正確性 (Scan 遍歷)
        for i in range(n):
            curr_w, curr_idxs = dp[k][i]
            prev_best_w, prev_best_idxs = prefix_max[k][i]
            if curr_w > prev_best_w:
                prefix_max[k][i+1] = (curr_w, curr_idxs)
            elif curr_w == prev_best_w and curr_w != -1:
                if not prev_best_idxs or curr_idxs < prev_best_idxs:
                    prefix_max[k][i+1] = (curr_w, curr_idxs)
                else:
                    prefix_max[k][i+1] = prefix_max[k][i] # 保持原樣
            else:
                # 如果當前 i 的結果比前一個差，則繼承前一個最好的
                if prev_best_w != -1:
                    prefix_max[k][i+1] = (prev_best_w, prev_best_idxs)
                else:
                    prefix_max[k][i+1] = (-1, [])

    # 最終尋找最大權重下的字典序最小索引列表
    ans_w = -1
    ans_idx = []
    for k in range(1, 5):
        for i in range(n):
            w, idxs = dp[k][i]
            if w > ans_w:
                ans_w = w
                ans_idx = idxs
            elif w == ans_w and w != -1:
                if not ans_idx or idxs < ans_idx:
                    ans_idx = idxs
    return ans_idx
